require_once dirname(__DIR__,3)."/includes/borrower_check.php";require_once dirname(__DIR__,3)."/config/db.php";require_once dirname(__DIR__,3)."/includes/activity_log_helper.php";require_once dirname(__DIR__,3)."/includes/notification_helper.php";require_once dirname(__DIR__,3)."/includes/adviser_endorsement_helper.php";
if(empty($_SESSION["csrf_token"]))$_SESSION["csrf_token"]=bin2hex(random_bytes(32));$facultyId=(int)$_SESSION["user_id"];$requestId=(int)($_GET["request_id"]??$_POST["request_id"]??0);if(!gsoIsApprovedFaculty($pdo,$facultyId))redirectWithFlash("browse.php","Faculty Endorsement access is not available.");
$load=function()use($pdo,$facultyId,$requestId){$s=$pdo->prepare("SELECT rr.*,b.full_name AS student_name,b.department AS student_department,r.resource_name,r.resource_type,r.category FROM resource_requests rr JOIN users b ON b.user_id=rr.borrower_id JOIN resources r ON r.resource_id=rr.resource_id WHERE rr.request_id=:rid AND rr.adviser_user_id=:uid LIMIT 1");$s->execute([":rid"=>$requestId,":uid"=>$facultyId]);return $s->fetch(PDO::FETCH_ASSOC);};$request=$load();if(!$request){http_response_code(404);exit("Endorsement not found.");}
if($_SERVER["REQUEST_METHOD"]==="POST"){
 if(!hash_equals((string)$_SESSION["csrf_token"],(string)($_POST["csrf_token"]??"")))redirectWithFlash("endorsement_detail.php?request_id={$requestId}","Invalid request token.");$action=(string)($_POST["action"]??"");$remarks=trim((string)($_POST["remarks"]??""));if(strlen($remarks)>1000)redirectWithFlash("endorsement_detail.php?request_id={$requestId}","Remarks must not exceed 1,000 characters.");
 try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT request_id,borrower_id,adviser_user_id,adviser_state FROM resource_requests WHERE request_id=:rid AND adviser_user_id=:uid FOR UPDATE");$s->execute([":rid"=>$requestId,":uid"=>$facultyId]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row||(string)$row["adviser_state"]!=="Pending Adviser")throw new DomainException("This request is no longer awaiting your decision.");$next=$action==="endorse"?"Endorsed":($action==="reject"?"Revision Required":"");if($next==="")throw new DomainException("Invalid endorsement action.");$u=$pdo->prepare("UPDATE resource_requests SET adviser_state=:state,status='Under Review',reviewed_by=NULL,reviewed_at=NULL,approved_by=NULL,approved_at=NULL WHERE request_id=:rid AND adviser_user_id=:uid AND adviser_state='Pending Adviser'");$u->execute([":state"=>$next,":rid"=>$requestId,":uid"=>$facultyId]);if($u->rowCount()!==1)throw new DomainException("A decision was already recorded.");$c=$pdo->prepare("SELECT COALESCE(MAX(cycle_no),1) FROM request_adviser_history WHERE request_id=:rid");$c->execute([":rid"=>$requestId]);$cycle=(int)$c->fetchColumn();$histAction=$action==="endorse"?"Endorsed":"Returned for Revision";$pdo->prepare("INSERT INTO request_adviser_history(request_id,adviser_user_id,cycle_no,action,remarks,acted_by) VALUES(:rid,:adviser,:cycle,:action,:remarks,:actor)")->execute([":rid"=>$requestId,":adviser"=>$facultyId,":actor"=>$facultyId,":cycle"=>$cycle,":action"=>$histAction,":remarks"=>$remarks!==""?$remarks:null]);$ref="REQ-".str_pad((string)$requestId,3,"0",STR_PAD_LEFT);createNotification($pdo,(int)$row["borrower_id"],$action==="endorse"?"adviser_endorsed":"adviser_revision",$action==="endorse"?"Request Endorsed":"Revision Requested",$action==="endorse"?"Your Adviser endorsed {$ref}. It returned to the GSO Head for review.":"Your Adviser returned {$ref} for revision.","adviser_request.php?request_id={$requestId}");if($action==="endorse")gsoNotifyApprovedAdmins($pdo,"adviser_endorsed","Adviser Endorsement Completed","{$ref} is ready for GSO Head review.","view_request.php?request_id={$requestId}");addActivityLog($pdo,$facultyId,$action==="endorse"?"Request Endorsed":"Request Returned for Revision","Faculty adviser decided request #{$requestId}.");$pdo->commit();redirectWithFlash("endorsements.php",$action==="endorse"?"Request endorsed and returned to GSO Head review.":"Request returned to the Student for revision.","success");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();redirectWithFlash("endorsement_detail.php?request_id={$requestId}",$e instanceof DomainException?$e->getMessage():"The decision could not be recorded.");}
}
$history=gsoAdviserHistory($pdo,$requestId);$pageTitle="Endorsement Detail";$activePage="endorsements";require dirname(__DIR__,3)."/includes/header.php";require dirname(__DIR__,3)."/includes/borrower_sidebar.php";?>
<div class="main-content"><?php require dirname(__DIR__,3)."/includes/borrower_topbar.php";?><main class="page-content"><section class="card"><h2>REQ-<?php echo str_pad((string)$requestId,3,'0',STR_PAD_LEFT);?></h2><p><strong>Student:</strong> <?php echo htmlspecialchars($request['student_name']);?> — <?php echo htmlspecialchars((string)$request['student_department']);?></p><p><strong>Resource:</strong> <?php echo htmlspecialchars($request['resource_name']);?> (<?php echo htmlspecialchars($request['resource_type']);?>), quantity <?php echo (int)$request['quantity'];?></p><p><strong>Schedule:</strong> <?php echo htmlspecialchars((string)$request['date_needed'].' '.(string)$request['start_time'].'–'.(string)$request['end_time']);?></p><p><strong>Purpose:</strong> <?php echo nl2br(htmlspecialchars((string)$request['notes']));?></p><p><strong>Status:</strong> <?php echo htmlspecialchars($request['adviser_state']);?></p></section><?php if($request['adviser_state']==='Pending Adviser'):?><section class="card"><form method="post"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']);?>"><input type="hidden" name="request_id" value="<?php echo $requestId;?>"><label>Optional remarks<textarea name="remarks" maxlength="1000"></textarea></label><button name="action" value="endorse" class="admin-btn primary-btn">Endorse Request</button><button name="action" value="reject" class="admin-btn">Reject Request / Return for Revision</button></form></section><?php endif;?><section class="card"><h3>History</h3><ul><?php foreach($history as $h):?><li>Cycle <?php echo (int)$h['cycle_no'];?> — <?php echo htmlspecialchars($h['action']);?> by <?php echo htmlspecialchars($h['actor_name']);?><?php if($h['remarks']!==null):?>: <?php echo nl2br(htmlspecialchars($h['remarks']));?><?php endif;?></li><?php endforeach;?></ul></section></main></div><?php require dirname(__DIR__,3)."/includes/footer.php";
